-- SQLite 建表
CREATE TABLE inspection_run (           -- 每次巡检一行
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  run_at TEXT NOT NULL,                 -- ISO8601 时间戳
  total INTEGER, ok INTEGER, failed INTEGER
);
CREATE TABLE inspection_item (          -- 每台设备每条规则一行
  run_id INTEGER NOT NULL,
  host TEXT NOT NULL, rule TEXT NOT NULL,
  ok INTEGER NOT NULL,                  -- 0/1
  detail TEXT,                          -- 回显摘要或实测值
  UNIQUE(run_id, host, rule)            -- 防重跑插入重复（幂等）
);

import fcntl                      # Linux；Windows 可用 msvcrt.locking
lock = open("/tmp/inspect.lock", "w")
try:
    fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
except BlockingIOError:
    print("上一次巡检仍在执行，跳过本次"); raise SystemExit(0)
